func:
let raw = msg.payload;
if (typeof raw !== 'string') {
    raw = JSON.stringify(raw);
}
raw = raw.trim();

let isRelayed = false;
let isNode01 = false;
let relayNode = '';

// Deteksi Paket 1-Hop Relay: RELAY,TAG01,FEAT,...
if (raw.startsWith('RELAY,')) {
    isRelayed = true;
    let rParts = raw.split(',');
    relayNode = rParts[1] || 'TAG01';
    let featPos = raw.indexOf('FEAT,');
    if (featPos !== -1) {
        raw = raw.substring(featPos);
    }
} else if (raw.startsWith('NODE01,')) {
    isNode01 = true;
    let featPos = raw.indexOf('FEAT,');
    if (featPos !== -1) {
        raw = raw.substring(featPos);
    }
}

// Format: FEAT,a_total,g_total,a_max,a_min,g_mean,a_std,g_max,ax,ay,az,model_pred,triage_pred,hr,spo2,temp
if (!raw.startsWith('FEAT,')) {
    return null;
}

const parts = raw.split(',').map(s => s.trim());
if (parts.length < 13) {
    return null;
}

const a_total = parseFloat(parts[1]) || 1.0;
const g_total = parseFloat(parts[2]) || 0.0;
const a_max   = parseFloat(parts[3]) || 1.0;
const a_min   = parseFloat(parts[4]) || 1.0;
const g_mean  = parseFloat(parts[5]) || 0.0;
const a_std   = parseFloat(parts[6]) || 0.0;
const g_max   = parseFloat(parts[7]) || 0.0;
const ax      = parseFloat(parts[8]) || 0.0;
const ay      = parseFloat(parts[9]) || 0.0;
const az      = parseFloat(parts[10]) || 1.0;
const model_pred  = parseInt(parts[11]) || 0;
const triage_pred = parseInt(parts[12]) || 0;

const hr   = (parts.length > 13) ? parseInt(parts[13]) || 0 : 0;
const spo2 = (parts.length > 14) ? parseInt(parts[14]) || 0 : 0;
const temp = (parts.length > 15) ? parseFloat(parts[15]) || 36.6 : 36.6;

const triageInfo = {
    0: { code: 0, label: 'HIJAU - Normal', status: 'NORMAL', color: '#10B981', badge: 'pill-green' },
    1: { code: 1, label: 'KUNING - Kerja Aktif', status: 'KERJA_AKTIF', color: '#F59E0B', badge: 'pill-amber' },
    2: { code: 2, label: 'ORANYE - Waspada Dini', status: 'WASPADA_DINI', color: '#F97316', badge: 'pill-orange' },
    3: { code: 3, label: 'MERAH - Darurat SOS', status: 'DARURAT_JATUH', color: '#EF4444', badge: 'pill-red' },
    4: { code: 4, label: 'STANDBY - Jam Dilepas', status: 'STANDBY', color: '#94A3B8', badge: 'pill-gray' }
};

const tri = triageInfo[triage_pred] || triageInfo[0];

// Telemetri Mandiri Jam #01 (Bambang - Relawan SAR & Relay Host)
let hr01 = isNode01 ? hr : Math.floor(75 + (Math.sin(Date.now() / 3000) * 3));
let spo201 = isNode01 ? spo2 : 98;
let temp01 = isNode01 ? temp : 36.5;

const telemetry01 = {
    device_id: 'RESCUE-TAG-01',
    worker_id: 'WRK-001',
    worker_name: 'Bambang (Relawan/Relay)',
    sector: 'Sektor 7 (Akses Relawan)',
    location: {
        name: 'Sektor 7 (Akses Pos A)',
        lat: -8.2465,
        lng: 113.6965
    },
    triage: {
        code: isNode01 ? triage_pred : 0,
        label: isNode01 ? tri.label : 'HIJAU - Normal',
        status: isNode01 ? tri.status : 'NORMAL',
        color: isNode01 ? tri.color : '#10B981',
        is_emergency: isNode01 ? (triage_pred === 3) : false
    },
    vitals: {
        hr: hr01,
        spo2: spo201,
        temp: temp01,
        hr_text: (hr01 > 0 ? hr01 + ' BPM' : '76 BPM'),
        spo2_text: spo201 + '%',
        temp_text: temp01.toFixed(1) + '°C'
    },
    kinematics: {
        a_total: isNode01 ? a_total : 1.015,
        g_total: isNode01 ? g_total : 2.8,
        a_max: isNode01 ? a_max : 1.04,
        a_min: isNode01 ? a_min : 0.99,
        g_mean: isNode01 ? g_mean : 2.1,
        a_std: isNode01 ? a_std : 0.007,
        g_max: isNode01 ? g_max : 4.5,
        tinyml_pred: isNode01 ? model_pred : 0
    },
    network: {
        route: isRelayed ? '⇄ 1-Hop Relay Host Aktif' : '⇄ Direct + Relay Standby (Hop 1)',
        rssi: -65,
        frequency: 433.0,
        is_relayed: false
    },
    timestamp: new Date().toISOString()
};

// Telemetri Jam #02 (Agus Salim - Korban / Pasien Bawah Tanah)
const telemetry02 = {
    device_id: 'RESCUE-TAG-02',
    worker_id: 'WRK-002',
    worker_name: 'Agus Salim',
    sector: 'Sektor 7 (Lorong C-4)',
    location: {
        name: 'Sektor 7 (C-4 Level -120m)',
        lat: -8.2498,
        lng: 113.7012
    },
    triage: {
        code: triage_pred,
        label: tri.label,
        status: tri.status,
        color: tri.color,
        is_emergency: (triage_pred === 3)
    },
    vitals: {
        hr: hr,
        spo2: spo2,
        temp: temp,
        hr_text: (hr > 0) ? hr + ' BPM' : 'Mengukur...',
        spo2_text: (spo2 > 0) ? spo2 + '%' : '--%',
        temp_text: temp.toFixed(1) + '°C'
    },
    kinematics: {
        a_total: a_total,
        g_total: g_total,
        a_max: a_max,
        a_min: a_min,
        g_mean: g_mean,
        a_std: a_std,
        g_max: g_max,
        tinyml_pred: model_pred
    },
    network: {
        route: isRelayed ? ('1-Hop LoRa Relay via Jam #01 (' + relayNode + ')') : 'Direct LoRa P2P',
        rssi: isRelayed ? -78 : -68,
        frequency: 433.0,
        is_relayed: isRelayed
    },
    timestamp: new Date().toISOString()
};

let mqttMsgs = [];
let alertMsg = null;
let debug01 = null;
let debug02 = null;

if (isNode01) {
    mqttMsgs.push({ topic: 'rescue/tag/data', payload: telemetry01 });
    debug01 = { topic: '🟢 LIVE: Jam #01 (Bambang - Relawan)', payload: telemetry01 };
} else {
    mqttMsgs.push({ topic: 'rescue/tag/data', payload: telemetry02 });
    mqttMsgs.push({ topic: 'rescue/tag/data', payload: telemetry01 });
    debug02 = { topic: '🔴 LIVE: Jam #02 (Agus Salim - Korban)', payload: telemetry02 };
    debug01 = { topic: '🟢 LIVE: Jam #01 (Bambang - Relawan)', payload: telemetry01 };

    if (triage_pred === 3) {
        alertMsg = {
            topic: 'rescue/tag/alert',
            payload: {
                alert_type: 'SOS_FALL_CRITICAL',
                worker: 'Agus Salim (Jam Tangan #02)',
                sector: 'Sektor 7 (C-4)',
                triage: telemetry02.triage,
                vitals: hr + ' BPM · ' + spo2 + '% SpO2 · ' + temp + '°C',
                kinematics: 'Benturan ' + a_max.toFixed(2) + 'g + Imobilitas >30s',
                route: telemetry02.network.route,
                timestamp: telemetry02.timestamp
            }
        };
    }
}

const statusColors = { 0: 'green', 1: 'yellow', 2: 'yellow', 3: 'red', 4: 'grey' };
node.status({
    fill: statusColors[triage_pred] || 'green',
    shape: 'dot',
    text: (isNode01 ? 'Jam #01' : (isRelayed ? 'Jam #02 (Relay)' : 'Jam #02')) + ' | ' + tri.label.split(' - ')[0] + ' (' + hr + ' BPM)'
});

return [mqttMsgs, alertMsg, debug01, debug02];
